def merge_counts(left, right):
    merged = dict(left)
    for key, value in right.items():
        merged[key] = merged.get(key, 0) + value
    return merged

tests.test_counts.py:
import unittest
from counts import merge_counts

class MergeCountsTests(unittest.TestCase):
    def test_combines_keys(self):
        self.assertEqual(merge_counts({'a': 2}, {'a': 3, 'b': 1}), {'a': 5, 'b': 1})
    def test_does_not_mutate_inputs(self):
        left, right = {'a': 2}, {'b': 1}
        merge_counts(left, right)
        self.assertEqual(left, {'a': 2})
        self.assertEqual(right, {'b': 1})

