def rotate_pair(pair):
    if len(pair) != 2:
        raise ValueError('pair must contain two items')
    return pair[1], pair[0]

tests.test_pair_ops.py:
import unittest
from pair_ops import rotate_pair

class RotatePairTests(unittest.TestCase):
    def test_rotates_two_items(self):
        self.assertEqual(rotate_pair(('left', 'right')), ('right', 'left'))
    def test_rejects_other_lengths(self):
        with self.assertRaises(ValueError):
            rotate_pair(('only',))
